async function listAll(offset, acc) {
  const res = await tools.mcp__eval_deploys__list_deploys({ service: "checkout", limit: 5, offset });
  const text = res.content.map(c => c.text || JSON.stringify(c)).join("\n");
  acc.push(text);
  let next = null;
  try { const parsed = JSON.parse(text); if (parsed.next_offset !== undefined) next = parsed.next_offset; } catch(e) {}
  return { text, next };
}

let all = [];
let offset = 0;
for (let i = 0; i < 20; i++) {
  const { text, next } = await listAll(offset, all);
  if (next === null || next === undefined) break;
  offset = next;
}
const health = await tools.mcp__eval_deploys__get_service_health({ service: "checkout" });
return { deploys: all.join("\n---PAGE---\n"), health: health.content.map(c => c.text || JSON.stringify(c)).join("\n") };

